  XW += x[6] * 1.8015000000000001e+01;       // H2O
  XW += x[7] * 3.4014000000000003e+01;       // H2O2
  XW += x[8] * 3.1998000000000001e+01;       // O2
  XW += x[9] * 1.4026999999999999e+01;       // CH2
