  W += c[18] * 2.6037999999999997e+01; // C2H2
  W += c[19] * 2.7045999999999999e+01; // C2H3
  W += c[20] * 2.8053999999999998e+01; // C2H4
  W += c[21] * 2.9061999999999998e+01; // C2H5
  W += c[22] * 3.0070000000000000e+01; // C2H6
  W += c[23] * 4.3045000000000002e+01; // CH2CHO
  W += c[24] * 4.1073000000000000e+01; // aC3H5
  W += c[25] * 4.2081000000000003e+01; // C3H6
  W += c[26] * 4.3088999999999999e+01; // nC3H7
  W += c[27] * 5.6064000000000000e+01; // C2H3CHO
  W += c[28] * 5.5099999999999994e+01; // C4H7
  W += c[29] * 5.6107999999999997e+01; // C4H81
  W += c[30] * 5.7116000000000000e+01; // pC4H9
  W += c[31] * 6.9126999999999995e+01; // C5H9
  W += c[32] * 7.0134999999999991e+01; // C5H10
