  W += c[38] * 1.1221599999999999e+02; // C8H16
  W += c[39] * 1.1322399999999999e+02; // PXC8H17
  W += c[40] * 1.2624299999999999e+02; // C9H18
  W += c[41] * 1.2725099999999999e+02; // PXC9H19
  W += c[42] * 1.4026999999999998e+02; // C10H20
  W += c[43] * 1.4127799999999999e+02; // PXC10H21
  W += c[44] * 1.6933199999999999e+02; // PXC12H25
  W += c[45] * 1.6933199999999999e+02; // SXC12H25
  W += c[46] * 1.6933199999999999e+02; // S3XC12H25
  W += c[47] * 1.6832400000000001e+02; // C12H24
