    const amrex::Real qf = Corr * k_f * (sc[1] * sc[9]);
    const amrex::Real qr = Corr * k_f *
                           (kc_fast ? (inv_ge[11] * ge[1] * ge[9])
                                    : exp(-(g_RT[1] + g_RT[9] - g_RT[11]))) *
                           (refC) * (sc[11]);
    const amrex::Real qdot = qf - qr;
    wdot[1] -= qdot;
    wdot[9] -= qdot;
    wdot[11] += qdot;
